func  (this *weex) ParseTrade(trade interface{}, optionalArgs ...interface{}) interface{}  {
    //
    // fetchTrades (public)
    //
    //     {
    //         "symbol": "BTCUSDT_SPBL",
    //         "tradeId": "778a5376-a0b6-4c8f-ab64-dd6ea40f896e",
    //         "fillTime": 1743668713364,
    //         "fillPrice": "83609.7",
    //         "fillQuantity": "0.00011400",
    //         "tradeValue": "9.531505800",
    //         "bestMatch": true,
    //         "buyerMaker": true
    //     }
    //
    // fetchMyTrades (private)
    //
    //     {
    //         "accountId": "590105411156181178",
    //         "symbol": "WXTUSDT_SPBL",
    //         "baseCoin": "WXT",
    //         "quoteCoin": "USDT",
    //         "orderId": "602929507946463674",
    //         "fillId": "602929507971629498",
    //         "orderType": "",
    //         "side": "buy",
    //         "fillPrice": "",
    //         "fillQuantity": "10",
    //         "fillTotalAmount": "0.10476",
    //         "fees": "0.01",
    //         "cTime": "1743749596589"
    //     }
    //
    market := GetArg(optionalArgs, 0, nil)
    _ = market
    var marketId interface{} = this.SafeString(trade, "symbol")
    var symbol interface{} = this.SafeSymbol(marketId, market)
    var id interface{} = this.SafeString2(trade, "tradeId", "fillId")
    var orderId interface{} = this.SafeString(trade, "orderId")
    var timestamp interface{} = this.SafeInteger2(trade, "fillTime", "cTime")
    var priceString interface{} = this.SafeString2(trade, "fillPrice", "fillPrice")
    var amountString interface{} = this.SafeString(trade, "fillQuantity")
    var costString interface{} = this.SafeString2(trade, "tradeValue", "fillTotalAmount")
    var side interface{} = this.SafeString(trade, "side")
    var takerOrMaker interface{} = nil
    var buyerMaker interface{} = this.SafeBool(trade, "buyerMaker")
    if IsTrue(!IsEqual(buyerMaker, nil)) {
        takerOrMaker = Ternary(IsTrue(buyerMaker), "maker", "taker")
    }
    var feeString interface{} = this.SafeString(trade, "fees")
    var fee interface{} = nil
    if IsTrue(!IsEqual(feeString, nil)) {
        fee = map[string]interface{} {
            "cost": feeString,
            "currency": nil,
        }
    }
    return this.SafeTrade(map[string]interface{} {
        "info": trade,
        "id": id,
        "order": orderId,
        "timestamp": timestamp,
        "datetime": this.Iso8601(timestamp),
        "symbol": symbol,
        "type": nil,
        "side": side,
        "amount": amountString,
        "price": priceString,
        "cost": costString,
        "takerOrMaker": takerOrMaker,
        "fee": fee,
    }, market)
}
